export function bindVersionHistory({flush,receive,openDialog,esc,toast}){
 const request=async(action,data)=>{const response=await fetch('/api/versions'+action,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const value=await response.json();if(!response.ok)throw Error(value.error);return value;};
 const guard=fn=>async()=>{try{await fn();}catch(error){toast(error.message);const node=document.querySelector('#version-message');if(node)node.textContent=error.message;}};
 const size=bytes=>`${(bytes/1024**3).toFixed(2)} GiB`;
 const manage=guard(async()=>{
  await flush();const stats=await request('/status');
  openDialog('历史数据管理',`<p>当前占用 ${size(stats.bytes)} / ${size(stats.limit)}，共 ${stats.count} 个版本，其中命名版本 ${stats.named} 个。</p><p>上次自动清理：${stats.lastCleanup?esc(new Date(stats.lastCleanup).toLocaleString('zh-CN')):'尚未执行'}。每 7 天清理普通版本，保留各工作区最新恢复点与命名版本。</p>${stats.error?`<p class="error">${esc(stats.error)}</p>`:''}<p id="version-message" class="error"></p><div class="actions"><button data-clean="7d">清理 7 天前</button><button data-clean="30d">清理 30 天前</button><button data-clean="all">清理全部普通历史</button><button id="version-back">返回历史</button></div>`);
  document.querySelector('#version-back').onclick=()=>show(false);
  for(const button of document.querySelectorAll('[data-clean]'))button.onclick=guard(async()=>{
   const mode=button.dataset.clean,plan=await request('/cleanup',{mode,preview:true});
   openDialog('确认清理历史',`<p>将删除当前工作区 ${plan.count} 个普通版本。最新恢复点和命名版本保留。删除后无法从历史中找回这些版本。</p><p>目前历史库实际占用 ${size(plan.bytes)}；释放量以清理后文件大小为准。</p><p id="version-message" class="error"></p><div class="actions"><button id="version-cancel">返回管理</button><button id="version-confirm" class="danger" ${plan.count?'':'disabled'}>确认清理</button></div>`);
   document.querySelector('#version-cancel').onclick=manage;
   document.querySelector('#version-confirm').onclick=guard(async()=>{const result=await request('/cleanup',{mode,signature:plan.signature});toast(`已清理 ${result.removed} 个版本，实际释放 ${size(Math.max(0,result.before-result.after))}`);await manage();});
  });
 });
 const show=restoreMode=>guard(async()=>{
  openDialog(restoreMode?'还原配置':'历史版本',`<p class="hint">正在读取历史版本，请稍候…</p><p id="version-message" class="error"></p>`);
  await flush();const [{versions},stats]=await Promise.all([request(''),request('/status')]);
  openDialog(restoreMode?'还原配置':'历史版本',`<p>编辑内容及时保存在本机；普通历史按编辑阶段生成，每 7 天自动清理。命名版本长期保留，全部历史占用 ${size(stats.bytes)}。</p><p id="version-message" class="error"></p><div class="actions"><button id="version-name">保存命名版本</button><button id="version-manage">历史数据管理</button></div>${versions.map(v=>`<section class="history-item"><div><strong>${v.name?esc(v.name):`版本 ${v.revision}`}</strong><time>${esc(new Date(v.at).toLocaleString('zh-CN'))}</time><p>${esc(v.reason)}</p></div><div><button data-version="${esc(v.id)}">${restoreMode?'查看差异并还原':'查看差异'}</button>${v.pinned?`<button data-delete-named="${esc(v.id)}">删除命名版本</button>`:''}</div></section>`).join('')||'<p>尚无历史版本。</p>'}`);
  document.querySelector('#version-manage').onclick=manage;
  document.querySelector('#version-name').onclick=()=>{openDialog('保存命名版本',`<label>版本名称<input id="version-name-input" maxlength="80" placeholder="例如：国庆活动价格确认版"></label><p id="version-message" class="error"></p><div class="actions"><button id="version-name-save" class="primary">保存</button><button id="version-back">返回历史</button></div>`);document.querySelector('#version-back').onclick=()=>show(restoreMode);document.querySelector('#version-name-save').onclick=guard(async()=>{await request('/name',{name:document.querySelector('#version-name-input').value});toast('命名版本已保存');await show(restoreMode);});};
  for(const button of document.querySelectorAll('[data-delete-named]'))button.onclick=()=>{const id=button.dataset.deleteNamed;openDialog('删除命名版本',`<p>删除后无法从历史中找回这个版本。</p><p id="version-message" class="error"></p><div class="actions"><button id="version-delete-confirm" class="danger">确认删除</button><button id="version-back">返回历史</button></div>`);document.querySelector('#version-back').onclick=()=>show(restoreMode);document.querySelector('#version-delete-confirm').onclick=guard(async()=>{await request('/delete-named',{id});await show(restoreMode);});};
  for(const button of document.querySelectorAll('[data-version]'))button.onclick=guard(async()=>{const preview=await request('/preview',{id:button.dataset.version});openDialog('还原版本预览',`<p>将还原至版本 ${preview.revision}，涉及 ${preview.changes.length} 条业务记录。确认前请检查以下差异。</p><p id="version-message" class="error"></p>${preview.changes.map(c=>`<details><summary>${esc(c.type)} · ${esc(c.name)}</summary><pre>${esc(JSON.stringify({当前:c.before,还原后:c.after},null,2))}</pre></details>`).join('')}<div class="actions"><button id="version-back">返回历史</button><button id="version-apply" class="primary" ${preview.changes.length?'':'disabled'}>备份当前并还原</button></div>`);document.querySelector('#version-back').onclick=()=>show(restoreMode);document.querySelector('#version-apply').onclick=guard(async()=>{document.querySelector('#version-apply').disabled=true;try{await request('/restore',{id:preview.id,hash:preview.hash,baseRevision:preview.baseRevision});document.querySelector('#dialog').close();await receive();toast('已还原并保存为新版本');await show(restoreMode);}catch(e){document.querySelector('#version-apply').disabled=false;throw e;}});});
 })();
 return {open:()=>show(false),restore:()=>show(true),manage};
}
